import { BallotData } from 'ballotdata';

const client = new BallotData(); // reads BALLOTDATA_API_KEY

// Reconnects by itself and resumes from the last event. Save the cursor to
// pick up where you stopped after a restart.
const stream = client.stream.connect(
  { subscription: 'CA labor', cursor: await loadCursor() },
  { onCursor: (cursor) => saveCursor(cursor) },
);
for await (const message of stream) {
  if (message.type === 'endorsement') console.log(message.event);
}

